SET NOCOUNT ON; SET XACT_ABORT ON; SET ANSI_NULLS ON; SET QUOTED_IDENTIFIER ON;
GO
IF OBJECT_ID(N'loyalty.RetailerReferralConfigurations',N'U') IS NULL
CREATE TABLE loyalty.RetailerReferralConfigurations(ConfigurationId tinyint NOT NULL CONSTRAINT PK_RetailerReferralConfigurations PRIMARY KEY,IsEnabled bit NOT NULL DEFAULT(0),ReferrerRewardCoins int NOT NULL DEFAULT(0),WelcomeRewardCoins int NOT NULL DEFAULT(0),CoinValidityDays int NOT NULL DEFAULT(365),MaximumRewardedReferralsPerTenantMonth int NOT NULL DEFAULT(10),MaximumCoinsPerTenantMonth int NOT NULL DEFAULT(2000),ProgramTerms nvarchar(2000) NULL,ProgramMessage nvarchar(500) NULL,CreatedOn datetimeoffset NOT NULL DEFAULT(SYSUTCDATETIME()),CreatedBy nvarchar(256) NULL,ModifiedOn datetimeoffset NULL,ModifiedBy nvarchar(256) NULL,RowVersion rowversion NOT NULL,CONSTRAINT CK_RetailerReferralConfigurations_Values CHECK(ConfigurationId=1 AND ReferrerRewardCoins>=0 AND WelcomeRewardCoins>=0 AND CoinValidityDays BETWEEN 1 AND 3650 AND MaximumRewardedReferralsPerTenantMonth>=1 AND MaximumCoinsPerTenantMonth>=1));
IF NOT EXISTS(SELECT 1 FROM loyalty.RetailerReferralConfigurations WHERE ConfigurationId=1) INSERT loyalty.RetailerReferralConfigurations(ConfigurationId) VALUES(1);
GO
IF OBJECT_ID(N'loyalty.RetailerRewardWallets',N'U') IS NULL
CREATE TABLE loyalty.RetailerRewardWallets(WalletId uniqueidentifier NOT NULL CONSTRAINT PK_RetailerRewardWallets PRIMARY KEY,TenantId uniqueidentifier NOT NULL CONSTRAINT UQ_RetailerRewardWallets_Tenant UNIQUE,CreatedOn datetimeoffset NOT NULL DEFAULT(SYSUTCDATETIME()),CreatedBy nvarchar(256) NULL,ModifiedOn datetimeoffset NULL,ModifiedBy nvarchar(256) NULL,RowVersion rowversion NOT NULL,CONSTRAINT FK_RetailerRewardWallets_Tenant FOREIGN KEY(TenantId) REFERENCES core.Tenants(TenantId));
GO
INSERT loyalty.RetailerRewardWallets(WalletId,TenantId,CreatedBy) SELECT NEWID(),TenantId,N'V46 retailer rewards' FROM core.Tenants t WHERE NOT EXISTS(SELECT 1 FROM loyalty.RetailerRewardWallets w WHERE w.TenantId=t.TenantId);
GO
IF OBJECT_ID(N'loyalty.RetailerReferralCodes',N'U') IS NULL
BEGIN
CREATE TABLE loyalty.RetailerReferralCodes(RetailerReferralCodeId uniqueidentifier NOT NULL CONSTRAINT PK_RetailerReferralCodes PRIMARY KEY,TenantId uniqueidentifier NOT NULL CONSTRAINT UQ_RetailerReferralCodes_Tenant UNIQUE,ReferralCode varchar(20) NOT NULL CONSTRAINT UQ_RetailerReferralCodes_Code UNIQUE,IsActive bit NOT NULL DEFAULT(1),CreatedOn datetimeoffset NOT NULL DEFAULT(SYSUTCDATETIME()),CreatedBy nvarchar(256) NULL,ModifiedOn datetimeoffset NULL,ModifiedBy nvarchar(256) NULL,RowVersion rowversion NOT NULL,CONSTRAINT FK_RetailerReferralCodes_Tenant FOREIGN KEY(TenantId) REFERENCES core.Tenants(TenantId),CONSTRAINT CK_RetailerReferralCodes_Format CHECK(ReferralCode=UPPER(ReferralCode) AND LEN(ReferralCode) BETWEEN 6 AND 20));
CREATE INDEX IX_RetailerReferralCodes_Resolve ON loyalty.RetailerReferralCodes(ReferralCode,IsActive) INCLUDE(TenantId);
END;
GO
IF OBJECT_ID(N'loyalty.RetailerReferrals',N'U') IS NULL
BEGIN
CREATE TABLE loyalty.RetailerReferrals(RetailerReferralId uniqueidentifier NOT NULL CONSTRAINT PK_RetailerReferrals PRIMARY KEY,ReferrerTenantId uniqueidentifier NOT NULL,ReferredTenantId uniqueidentifier NOT NULL CONSTRAINT UQ_RetailerReferrals_Referred UNIQUE,RetailerReferralCodeId uniqueidentifier NOT NULL,Status nvarchar(20) NOT NULL DEFAULT(N'PENDING'),QualificationType nvarchar(30) NOT NULL DEFAULT(N'TENANT_ACTIVATED'),CaptureSource nvarchar(30) NOT NULL DEFAULT(N'WEB'),AttributionLockedAt datetimeoffset NULL,QualifiedAt datetimeoffset NULL,RewardedAt datetimeoffset NULL,ReversedAt datetimeoffset NULL,RejectionReason nvarchar(500) NULL,CreatedOn datetimeoffset NOT NULL DEFAULT(SYSUTCDATETIME()),CreatedBy nvarchar(256) NULL,ModifiedOn datetimeoffset NULL,ModifiedBy nvarchar(256) NULL,RowVersion rowversion NOT NULL,CONSTRAINT CK_RetailerReferrals_Safety CHECK(ReferrerTenantId<>ReferredTenantId AND Status IN(N'PENDING',N'QUALIFIED',N'REWARDED',N'REJECTED',N'CANCELLED',N'REVERSED')),CONSTRAINT FK_RetailerReferrals_Referrer FOREIGN KEY(ReferrerTenantId) REFERENCES core.Tenants(TenantId),CONSTRAINT FK_RetailerReferrals_Referred FOREIGN KEY(ReferredTenantId) REFERENCES core.Tenants(TenantId),CONSTRAINT FK_RetailerReferrals_Code FOREIGN KEY(RetailerReferralCodeId) REFERENCES loyalty.RetailerReferralCodes(RetailerReferralCodeId));
CREATE INDEX IX_RetailerReferrals_ReferrerStatus ON loyalty.RetailerReferrals(ReferrerTenantId,Status,CreatedOn DESC) INCLUDE(ReferredTenantId,RewardedAt);
END;
GO
IF OBJECT_ID(N'loyalty.RetailerCoinLedger',N'U') IS NULL
BEGIN
CREATE TABLE loyalty.RetailerCoinLedger(CoinTransactionId uniqueidentifier NOT NULL CONSTRAINT PK_RetailerCoinLedger PRIMARY KEY,WalletId uniqueidentifier NOT NULL,TenantId uniqueidentifier NOT NULL,TransactionType nvarchar(30) NOT NULL,Coins int NOT NULL,ReferenceType nvarchar(40) NULL,ReferenceId uniqueidentifier NULL,EventKey nvarchar(250) NOT NULL,Description nvarchar(500) NULL,ExpiresAt datetimeoffset NULL,CreatedOn datetimeoffset NOT NULL DEFAULT(SYSUTCDATETIME()),CreatedBy nvarchar(256) NULL,CONSTRAINT UQ_RetailerCoinLedger_Event UNIQUE(TenantId,EventKey),CONSTRAINT CK_RetailerCoinLedger_NonZero CHECK(Coins<>0),CONSTRAINT FK_RetailerCoinLedger_Wallet FOREIGN KEY(WalletId) REFERENCES loyalty.RetailerRewardWallets(WalletId),CONSTRAINT FK_RetailerCoinLedger_Tenant FOREIGN KEY(TenantId) REFERENCES core.Tenants(TenantId));
CREATE INDEX IX_RetailerCoinLedger_TenantCreated ON loyalty.RetailerCoinLedger(TenantId,CreatedOn DESC) INCLUDE(Coins,TransactionType,ReferenceType,ReferenceId,ExpiresAt);
END;
GO
IF OBJECT_ID(N'loyalty.RetailerReferralAuditEvents',N'U') IS NULL CREATE TABLE loyalty.RetailerReferralAuditEvents(RetailerReferralAuditEventId bigint IDENTITY PRIMARY KEY,RetailerReferralId uniqueidentifier NULL,ReferrerTenantId uniqueidentifier NULL,ReferredTenantId uniqueidentifier NULL,EventType nvarchar(50) NOT NULL,Reason nvarchar(500) NULL,OccurredOn datetimeoffset NOT NULL DEFAULT(SYSUTCDATETIME()),Actor nvarchar(256) NULL,SystemSource nvarchar(100) NULL,CONSTRAINT FK_RetailerReferralAuditEvents_Referral FOREIGN KEY(RetailerReferralId) REFERENCES loyalty.RetailerReferrals(RetailerReferralId));
GO
CREATE OR ALTER VIEW loyalty.RetailerRewardWalletBalance AS SELECT w.WalletId,w.TenantId,ISNULL(SUM(l.Coins),0) AvailableCoins,ISNULL(SUM(CASE WHEN l.Coins>0 THEN l.Coins ELSE 0 END),0) TotalEarned,ISNULL(SUM(CASE WHEN l.Coins<0 THEN -l.Coins ELSE 0 END),0) TotalDebited FROM loyalty.RetailerRewardWallets w LEFT JOIN loyalty.RetailerCoinLedger l ON l.WalletId=w.WalletId AND l.TenantId=w.TenantId GROUP BY w.WalletId,w.TenantId;
GO
CREATE OR ALTER PROCEDURE loyalty.CaptureRetailerReferral @ReferredTenantId uniqueidentifier,@ReferralCode varchar(20),@CaptureSource nvarchar(30)=N'WEB',@CreatedBy nvarchar(256)=NULL AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;BEGIN TRAN;DECLARE @referrer uniqueidentifier,@codeId uniqueidentifier,@enabled bit;SELECT @enabled=IsEnabled FROM loyalty.RetailerReferralConfigurations WHERE ConfigurationId=1;IF ISNULL(@enabled,0)=0 THROW 51301,N'The retailer referral program is disabled.',1;SELECT @referrer=TenantId,@codeId=RetailerReferralCodeId FROM loyalty.RetailerReferralCodes WITH(UPDLOCK,HOLDLOCK) WHERE ReferralCode=UPPER(LTRIM(RTRIM(@ReferralCode))) AND IsActive=1;IF @referrer IS NULL THROW 51302,N'The retailer referral code is invalid or inactive.',1;IF NOT EXISTS(SELECT 1 FROM core.Tenants WHERE TenantId=@ReferredTenantId AND IsActive=1) THROW 51303,N'The referred tenant is not active.',1;IF @referrer=@ReferredTenantId THROW 51304,N'Retailer self-referrals are not allowed.',1;IF EXISTS(SELECT 1 FROM loyalty.RetailerReferrals WHERE ReferredTenantId=@ReferredTenantId) THROW 51305,N'This tenant already has a referral attribution.',1;INSERT loyalty.RetailerReferrals(RetailerReferralId,ReferrerTenantId,ReferredTenantId,RetailerReferralCodeId,Status,QualificationType,CaptureSource,AttributionLockedAt,CreatedBy) VALUES(NEWID(),@referrer,@ReferredTenantId,@codeId,N'PENDING',N'TENANT_ACTIVATED',UPPER(@CaptureSource),SYSUTCDATETIME(),@CreatedBy);DECLARE @id uniqueidentifier=(SELECT TOP(1)RetailerReferralId FROM loyalty.RetailerReferrals WHERE ReferredTenantId=@ReferredTenantId ORDER BY CreatedOn DESC);INSERT loyalty.RetailerReferralAuditEvents(RetailerReferralId,ReferrerTenantId,ReferredTenantId,EventType,Actor,SystemSource) VALUES(@id,@referrer,@ReferredTenantId,N'ATTRIBUTION_CAPTURED',@CreatedBy,N'RETAILER_REFERRAL');COMMIT;SELECT @id;END;
GO
CREATE OR ALTER PROCEDURE loyalty.RewardRetailerReferral @ReferredTenantId uniqueidentifier,@EventKey nvarchar(200),@CreatedBy nvarchar(256)=NULL AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;BEGIN TRAN;DECLARE @id uniqueidentifier,@referrer uniqueidentifier,@status nvarchar(20),@lock int,@refReward int,@welcomeReward int,@validity int,@maxReferrals int,@maxCoins int,@config bit,@resource nvarchar(255);SET @resource=CONCAT(N'loyalty:retailer-referral:',@ReferredTenantId);EXEC @lock=sys.sp_getapplock @Resource=@resource,@LockMode=N'Exclusive',@LockOwner=N'Transaction',@LockTimeout=10000;IF @lock<0 THROW 51306,N'Unable to lock the retailer referral.',1;SELECT @id=RetailerReferralId,@referrer=ReferrerTenantId,@status=Status FROM loyalty.RetailerReferrals WITH(UPDLOCK,HOLDLOCK) WHERE ReferredTenantId=@ReferredTenantId;IF @id IS NULL THROW 51307,N'Retailer referral attribution was not found.',1;IF @status=N'REWARDED' BEGIN COMMIT;RETURN;END;IF @status NOT IN(N'PENDING',N'QUALIFIED') THROW 51308,N'Retailer referral is not eligible for reward.',1;SELECT @config=IsEnabled,@refReward=ReferrerRewardCoins,@welcomeReward=WelcomeRewardCoins,@validity=CoinValidityDays,@maxReferrals=MaximumRewardedReferralsPerTenantMonth,@maxCoins=MaximumCoinsPerTenantMonth FROM loyalty.RetailerReferralConfigurations WITH(UPDLOCK,HOLDLOCK) WHERE ConfigurationId=1;IF ISNULL(@config,0)=0 THROW 51309,N'The retailer referral program is disabled.',1;IF @status=N'PENDING' UPDATE loyalty.RetailerReferrals SET Status=N'QUALIFIED',QualifiedAt=SYSUTCDATETIME(),ModifiedOn=SYSUTCDATETIME(),ModifiedBy=@CreatedBy WHERE RetailerReferralId=@id;IF (SELECT COUNT(*) FROM loyalty.RetailerReferrals WHERE ReferrerTenantId=@referrer AND Status=N'REWARDED' AND RewardedAt>=DATEFROMPARTS(YEAR(SYSUTCDATETIME()),MONTH(SYSUTCDATETIME()),1))>=@maxReferrals THROW 51310,N'The referrer monthly reward limit has been reached.',1;IF (SELECT ISNULL(SUM(Coins),0) FROM loyalty.RetailerCoinLedger WHERE TenantId=@referrer AND Coins>0 AND CreatedOn>=DATEFROMPARTS(YEAR(SYSUTCDATETIME()),MONTH(SYSUTCDATETIME()),1))+@refReward>@maxCoins THROW 51311,N'The referrer monthly coin limit has been reached.',1;DECLARE @rewardedAt datetimeoffset=SYSUTCDATETIME(),@expiry datetimeoffset=DATEADD(day,@validity,SYSUTCDATETIME()),@wallet uniqueidentifier,@event nvarchar(250);SELECT @wallet=WalletId FROM loyalty.RetailerRewardWallets WITH(UPDLOCK,HOLDLOCK) WHERE TenantId=@referrer;IF @wallet IS NULL BEGIN SET @wallet=NEWID();INSERT loyalty.RetailerRewardWallets(WalletId,TenantId,CreatedBy) VALUES(@wallet,@referrer,N'RETAILER_REFERRAL');END;SET @event=CONCAT(N'RETAILER_REFERRAL:',@id,N':REFERRER');IF @refReward>0 INSERT loyalty.RetailerCoinLedger(CoinTransactionId,WalletId,TenantId,TransactionType,Coins,ReferenceType,ReferenceId,EventKey,Description,ExpiresAt,CreatedBy) SELECT NEWID(),@wallet,@referrer,N'REFERRAL_REWARD',@refReward,N'RETAILER_REFERRAL',@id,@event,N'Retailer referral reward',@expiry,@CreatedBy WHERE NOT EXISTS(SELECT 1 FROM loyalty.RetailerCoinLedger WHERE TenantId=@referrer AND EventKey=@event);SELECT @wallet=WalletId FROM loyalty.RetailerRewardWallets WITH(UPDLOCK,HOLDLOCK) WHERE TenantId=@ReferredTenantId;IF @wallet IS NULL BEGIN SET @wallet=NEWID();INSERT loyalty.RetailerRewardWallets(WalletId,TenantId,CreatedBy) VALUES(@wallet,@ReferredTenantId,N'RETAILER_REFERRAL');END;SET @event=CONCAT(N'RETAILER_REFERRAL:',@id,N':WELCOME');IF @welcomeReward>0 INSERT loyalty.RetailerCoinLedger(CoinTransactionId,WalletId,TenantId,TransactionType,Coins,ReferenceType,ReferenceId,EventKey,Description,ExpiresAt,CreatedBy) SELECT NEWID(),@wallet,@ReferredTenantId,N'WELCOME_REWARD',@welcomeReward,N'RETAILER_REFERRAL',@id,@event,N'Welcome reward for joining through a retailer referral',@expiry,@CreatedBy WHERE NOT EXISTS(SELECT 1 FROM loyalty.RetailerCoinLedger WHERE TenantId=@ReferredTenantId AND EventKey=@event);UPDATE loyalty.RetailerReferrals SET Status=N'REWARDED',RewardedAt=@rewardedAt,ModifiedOn=@rewardedAt,ModifiedBy=@CreatedBy WHERE RetailerReferralId=@id;INSERT loyalty.RetailerReferralAuditEvents(RetailerReferralId,ReferrerTenantId,ReferredTenantId,EventType,Actor,SystemSource) VALUES(@id,@referrer,@ReferredTenantId,N'REWARDS_CREDITED',@CreatedBy,N'RETAILER_REFERRAL');COMMIT;END;
GO
CREATE OR ALTER PROCEDURE loyalty.ExpireRetailerRewards @TenantId uniqueidentifier=NULL,@BatchSize int=1000,@CreatedBy nvarchar(256)=N'SYSTEM' AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;DECLARE @count int=0;DECLARE expired CURSOR LOCAL FAST_FORWARD FOR SELECT TOP(@BatchSize) l.CoinTransactionId,l.WalletId,l.TenantId,l.Coins FROM loyalty.RetailerCoinLedger l WHERE l.Coins>0 AND l.ExpiresAt<=SYSUTCDATETIME() AND(@TenantId IS NULL OR l.TenantId=@TenantId) AND NOT EXISTS(SELECT 1 FROM loyalty.RetailerCoinLedger x WHERE x.TenantId=l.TenantId AND x.EventKey=CONCAT(N'EXPIRY:',l.CoinTransactionId));DECLARE @id uniqueidentifier,@wallet uniqueidentifier,@tenant uniqueidentifier,@coins int;OPEN expired;FETCH NEXT FROM expired INTO @id,@wallet,@tenant,@coins;WHILE @@FETCH_STATUS=0 BEGIN BEGIN TRAN;INSERT loyalty.RetailerCoinLedger(CoinTransactionId,WalletId,TenantId,TransactionType,Coins,ReferenceType,ReferenceId,EventKey,Description,CreatedBy) SELECT NEWID(),@wallet,@tenant,N'EXPIRATION',-@coins,N'EXPIRATION',@id,CONCAT(N'EXPIRY:',@id),N'Retailer reward coins expired',@CreatedBy WHERE NOT EXISTS(SELECT 1 FROM loyalty.RetailerCoinLedger WHERE TenantId=@tenant AND EventKey=CONCAT(N'EXPIRY:',@id));IF @@ROWCOUNT=1 SET @count+=1;COMMIT;FETCH NEXT FROM expired INTO @id,@wallet,@tenant,@coins;END;CLOSE expired;DEALLOCATE expired;SELECT @count;END;
GO
DECLARE @feature uniqueidentifier=(SELECT FeatureId FROM core.Features WHERE FeatureKey=N'RETAILER_REFERRAL_REWARDS'),@parent uniqueidentifier=(SELECT FeatureId FROM core.Features WHERE FeatureKey=N'CUSTOMERS');IF @feature IS NULL BEGIN SET @feature=NEWID();INSERT core.Features(FeatureId,FeatureKey,Name,Description,ModuleKey,ReleaseState,IsActive,FeatureType,ParentFeatureId,Version,SortOrder,CreatedBy) VALUES(@feature,N'RETAILER_REFERRAL_REWARDS',N'Retailer Referral Rewards',N'Tenant-to-tenant KhataDhari Coins referral rewards.',N'COMMERCE',N'ACTIVE',1,N'MODULE',@parent,N'V2',76,N'V46 retailer referral rewards');END;MERGE core.PlanFeatures target USING(SELECT p.PlanId,@feature FeatureId,CONVERT(bit,CASE WHEN p.PlanKey=N'V2_COMMERCE' THEN 1 ELSE 0 END) IsEnabled FROM core.Plans p WHERE p.PlanKey IN(N'V1_DEFAULT',N'V2_COMMERCE')) source ON target.PlanId=source.PlanId AND target.FeatureId=source.FeatureId WHEN MATCHED THEN UPDATE SET IsEnabled=source.IsEnabled,ModifiedOn=SYSUTCDATETIME(),ModifiedBy=N'V46 retailer referral rewards' WHEN NOT MATCHED THEN INSERT(PlanFeatureId,PlanId,FeatureId,IsEnabled,CreatedBy) VALUES(NEWID(),source.PlanId,source.FeatureId,source.IsEnabled,N'V46 retailer referral rewards');INSERT core.TenantFeatures(TenantFeatureId,TenantId,FeatureId,IsEnabled,Reason,IsActive,CreatedBy) SELECT NEWID(),t.TenantId,@feature,0,N'Opt-in retailer referral rewards',1,N'V46 retailer referral rewards' FROM core.Tenants t WHERE NOT EXISTS(SELECT 1 FROM core.TenantFeatures tf WHERE tf.TenantId=t.TenantId AND tf.FeatureId=@feature);
GO
